        const FIT_UINT8 numMaps = subField->numMaps;
        const auto* map = subField->maps;
        for (FIT_UINT8 j = 0; j < numMaps; ++j, ++map)
        {
            const FIT_UINT8 refFieldNum = map->refFieldNum;
            const Field* refField;
